// === Tab: GlitchRect ===
class GlitchRect {
	constructor(pos, idx, sze, clr, frames) {
		this.pos = pos.copy();
		this.idx = idx.copy();
		this.first = this.pos.copy();
		this.sze = ~~sze;
		this.frames = frames;
		this.clr = clr;

		this.steps = 0;

		this.directions = [createVector(1, 0), createVector(0, 1), createVector(-1, 0), createVector(0, -1)];
		this.dir = ~~random(this.directions.length);

		this.positions = [];
		this.positions.push(this.pos);
		// this.randomWalk();
		this.posIdx = 0;

		const numJumps = ~~random(2, 5.4321);
		this.randomJump(numJumps);

		this.numLastPoss = 6;
		this.lastPoss = [];

		this.easing = random([easeInCubic, easeOutSine]);
		// console.log(this);
	}

	randomJump(n = 1) {
		for (let i = 0; i < n; i++) {
			// change dir
			// if (this.steps % this.sze === 0) {

			let newPos;

			this.dir += random([1, this.directions.length-1]); // jump to left (-1 = 3) or right
			this.dir = this.dir % this.directions.length;
			// console.log(this.dir);

			newPos = this.pos.copy();
			const steps = ~~random(3, 5);
			newPos.add(this.directions[this.dir].copy().mult(this.sze*steps));

			this.positions.push(newPos.copy());
			this.pos = newPos.copy();
		}
		this.positions.reverse();
	}

	positionEscape(num = 1) {
		let lastPos = this.positions[this.positions.length-1];
		for (let i = 0; i < 2; i++) this.positions.push(lastPos);
		let newPos = lastPos.copy();
		if (random() < 0.5) {
			newPos.x += this.sze * (this.idx.x > this.idx.z/2 ? -this.idx.x-1 : this.idx.z-this.idx.x);
		} else {
			newPos.y += this.sze * (this.idx.y > this.idx.z/2 ? -this.idx.y-1 : this.idx.z-this.idx.y);
		}
		this.positions.push(newPos);
		// this.positions.push(createVector(0, 0));
	}

	update() {
		// this.randomWalk();
		this.steps++;
		if ((this.steps % this.frames === 0) && (this.posIdx < (this.positions.length-1))) this.posIdx++;
	}

	show() {
		push();
		rectMode(CENTER);
		noStroke();
		const clr = this.clr;

		let pos = this.positions[this.posIdx].copy();
		if (this.posIdx < (this.positions.length-1)) {
			const nxt = this.positions[this.posIdx+1];
			const f = (this.steps % this.frames) / this.frames;
			pos = p5.Vector.lerp(pos, nxt, this.easing(f));
			this.lastPoss.push(pos.copy());
			if (this.lastPoss.length > this.numLastPoss) this.lastPoss.splice(0, 1);
		} else {
			if (this.lastPoss.length > 0) this.lastPoss.splice(0, 1);
		}

		if (this.lastPoss.length) {
			let clrTr = color(clr);
			clrTr.setAlpha(64);
			// clrTr = "#000000A0";
			fill(clrTr);
			for (const lastPos of this.lastPoss) {
				rect(lastPos.x, lastPos.y, this.sze * 0.7);			
			}
		} 

		fill(clr);
		rect(pos.x, pos.y, this.sze * 0.8);		

		pop();
	}
}

