let pal, BG, FG, glitchRects, S, MAR, startFrame;
const FPS = 30;

function setup() {
  createCanvas(windowWidth, windowHeight);
	S = max(width, height) * 0.8;
	MAR = max(width, height) * 0.1;
  describe("random positioned rectangles in a grid transforming to an ordered grid position with one empty cell while rotating whole scene by 90 degrees");
  frameRate(FPS);
	startFrame = frameCount;

	// choose palette and bg color
	pal = [...random(palettes)];
	shuffle(pal, true);
  BG = pal.splice(0, 1)[0]; //  + "A0"; // add some transparency for blur
	FG = getLerpedColor(pal, random());
	noStroke();

	// gen glitched rectangles
	const NUM = ~~random(4, 9);
	const PAD = S/(NUM+1);
	glitchRects = [];
  for (let j = 0; j < NUM; j++) {
	  for (let i = 0; i < NUM; i++) {
			const x = width/2 + (i-(NUM/2-0.5)) * PAD;
			const y = height/2 + (j-(NUM/2-0.5)) * PAD;
			const pos = createVector(x, y);
			const idx = createVector(i, j, NUM);
			glitchRects.push(new GlitchRect(pos, idx, PAD, random(pal) /* +"D0" */ , ~~(FPS/3)));
		}
	}
	shuffle(glitchRects, true);	
	// glitchRects.splice(0, 1); // delete random rect
	glitchRects.sort((a, b) => b.positions.length - a.positions.length);
	glitchRects[0].positionEscape(NUM); // reposition rect with most movements, to escape last

  loop();
}

function draw() {
	background(BG);
	const w2 = width/2, h2 = height/2;

	// rotate 1st two seconds
	if (frameCount < startFrame + 2 * FPS) {
		const pastFrames = frameCount - startFrame;
		const f = easeInOutElastic(1 - pastFrames / (2 * FPS)); // 1..0
		translate(w2, h2);
		rotate(f * -HALF_PI)
		translate(-w2, -h2);
	}

	// draw circle and lines background
	push()
	strokeWeight(2);
	stroke(FG);
	noFill();
	line(w2-S/2-MAR/2, h2, w2-MAR/2, h2);
	line(w2+MAR/2, h2, w2+S/2+MAR/2, h2);
	line(w2, h2-S/2-MAR/2, w2, h2-MAR/2);
	line(w2, h2+MAR/2, w2, h2+S/2+MAR/2);
	circle(width/2, height/2, S);
	pop();

	// animate and draw glitched rectangles
	for (let rect of glitchRects) {
		rect.update();
    rect.show();
  }

	// noLoop();
}


